if __name__ == "__main__":
    import json, re, sys
    lists = [globals()[n] for n in sys.argv[1:]] or [S5]
    for col, lang in enumerate(["en", "es", "fr", "de"], start=1):
        path = f"src/i18n/locales/{lang}.ts"
        s = open(path, encoding="utf-8").read()
        keys = set(json.loads(m) for m in re.findall(r'^\t("(?:[^"\\]|\\.)*"):', s, re.M))
        add = "".join(f"\t{json.dumps(row[0], ensure_ascii=False)}: {json.dumps(row[col], ensure_ascii=False)},\n" for L in lists for row in L if row[0] not in keys)
        end = "};\n\nexport default catalog;"
        assert end in s
        s = s.replace(end, add + end)
        open(path, "w", encoding="utf-8").write(s)
        print(lang, add.count("\n"))
